// Generado una sola vez a partir de public/logo-neumaticos-trivium.svg y
// src/app/icon.svg (base64 del SVG completo). Van embebidos como constantes
// de módulo — sin fs.readFile ni fetch — porque una ruta API dinámica (ej.
// /api/og/equivalencia) corre en vivo en el Worker de Cloudflare, donde
// /public no existe en el filesystem (readFile tira ENOENT) y un fetch a la
// propia URL del sitio puede colgarse (visto en producción: el endpoint no
// respondía más). Si se edita alguno de los dos SVG originales, hay que
// regenerar esto a mano: base64 -w0 <archivo>.
export const TRIVIUM_WORDMARK_SVG_BASE64 = "";
export const TRIVIUM_ICON_SVG_BASE64 = "";
